void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                int patientId = 0;

                int.TryParse(
                    Request.QueryString["contextId"],
                    out patientId
                );

                if (patientId > 0 &&
                    string.Equals(
                        Request.QueryString["context"],
                        "patient",
                        StringComparison.OrdinalIgnoreCase))
                {
                    // Only age / dob / gender are needed here, so read just those columns instead of
                    // materialising the whole Patient entity through LINQ to SQL (which breaks whenever
                    // any unrelated Patient column's type drifts from the dbml mapping).
                    DataSet pds = new DBHelper().ExecuteDataSet(
                        "SELECT age, dob, gender FROM Patient WHERE row_id = @Id",
                        new[] { new SqlParameter("@Id", patientId) },
                        CommandType.Text);

                    if (pds != null && pds.Tables.Count > 0 && pds.Tables[0].Rows.Count > 0)
                    {
                        DataRow prow = pds.Tables[0].Rows[0];
                        string age = "";

                        if (prow["age"] != DBNull.Value)
                        {
                            age = Convert.ToString(prow["age"]);
                        }
                        else if (prow["dob"] != DBNull.Value)
                        {
                            age =
                                (DateTime.Now.Year -
                                 Convert.ToDateTime(prow["dob"]).Year)
                                .ToString();
                        }
                        else
                        {
                            age = "_";
                        }

                        string gender =
                            prow["gender"] != DBNull.Value
                                ? Convert.ToString(prow["gender"])
                                : "_";

                        ClientScript.RegisterStartupScript(
                            GetType(),
                            "patientAgeGender",
                            "window.patientAgeGender = " +
                            HttpUtility.JavaScriptStringEncode(
                                age + "/" + gender,
                                true
                            ) +
                            ";",
                            true
                        );
                    }
                }
            }
        }

