// event bindings
$('#txtFu').on('change', onFuChange);

function doSave() {
            var note = $('#txtNote').val().trim();
            if (!note) { $('#txtNote').addClass('err').focus(); setTimeout(function () { $('#txtNote').removeClass('err'); }, 1500); return; }

            $('#btnSend').prop('disabled', true).html('<i class="fa-solid fa-spinner fa-spin"></i> Sending…');
            var ids = $('#hdnIds').val(), first = ids ? parseInt(ids.split(',')[0]) : 0;

            ajax('UniversalComm.aspx/SaveCommunication', {
                context: CTX, contextId: CID, note: note,
                assignedTo: first, assignedToIds: ids,
                followUpDate: $('#txtFu').val() || '', followUpTime: '',
                dueAction: $('#chkDue').is(':checked') ? 1 : 0, endComm: 0
            },
                function (d) {
                    try {
                        var r = JSON.parse(d);
                        if (r.ok) {
                            doReset();
                            toast('Saved!', 'ok');
                            // Switch to All tab so new record is visible
                            $('.ftab').removeClass('on');
                            $('.ftab[data-f="all"]').addClass('on');
                            FILT = 'all'; PAGE = 1;
                            // Silent refresh — no spinner
                            loadHistory(false);
                        } else {
                            alert('Error: ' + (r.error || 'Unknown'));
                        }
                    } catch (e) { alert('Parse error: ' + e.message); }
                    $('#btnSend').prop('disabled', false).html('<i class="fa-solid fa-paper-plane"></i>Send');
                },
                function (x) { alert('Server error: ' + x.status); $('#btnSend').prop('disabled', false).html('<i class="fa-solid fa-paper-plane"></i>Send'); }
            );
        }
